// Minimal local fallback for marked.parse to avoid CDN/Tracking Prevention failures.
// This provides a very small markdown-to-HTML conversion (line breaks -> <br>).
window.marked = {
  parse: function (text) {
    try {
      if (text == null) return "";
      return String(text).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\n/g, "<br>");
    } catch (e) {
      return String(text || "");
    }
  },
};


